:root {
  --ink: #24352d;
  --cream: #fffaf0;
  --mint: #bfe8d0;
  --coral: #ef7863;
}

.pass-card {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 14px;
  width: 460px;
  padding: 14px 16px;
  border: 2px solid var(--ink);
  border-radius: 16px;
  background: var(--cream);
  color: var(--ink);
}

.cat-icon {
  display: grid;
  flex: 0 0 46px;
  place-items: center;
  width: 46px;
  height: 46px;
  border-radius: 50%;
  background: var(--mint);
  font-size: 24px;
}

.pass-copy {
  flex: 1;
}

h2 {
  margin: 0 0 3px;
  font-size: 18px;
  line-height: 1.1;
}

p {
  margin: 0;
  font-size: 14px;
  line-height: 1.3;
}

button {
  padding: 9px 12px;
  border: 0;
  border-radius: 9px;
  background: var(--coral);
  color: var(--cream);
  font-size: 14px;
  font-weight: 700;
}
